query ProductionSetupOutput(
  $wherePSO: ProductionSetupOutputWhereInput,
  $setupMaterialIds: [String!]!
) {
  productionSetupOutput(where: $wherePSO) {
    edges {
      node {
        id
        produced
        scrapped
        quantity
        dist:workOrderProcessDistribution{
          id
          productionHistories(
            where:  {
              _not:  {
                scrap:  { _eq: false }
                suspect:  { _eq: false }
              } 
            }
          ){
            edges{
              node{
                _aggregate{
                  quantity{
                    sum
                  }
                }
              }
            }
          }
          scrap: productionHistories(
            where:  {
              scrap:  { _eq: true } 
            }
          ){
            edges{
              node{
                _aggregate{
                  quantity{
                    sum
                  }
                }
              }
            }
          }
          workOrderProcess{
            processId
            workOrder{ productId }            
          }
        }
        workunit{
          id
          productionSetupOperators{
            edges{
              node{
                userId
              }
            }
          }
          currentProductionRunId
          productionSetupMaterials(
            where:  {
               id:{
                _in: $setupMaterialIds
               }
            }
          ){
            edges {
              node {
                id
                serial
                productId
                quantity
                number
                serial
              }
            }
          }
        }
        productionSetupBoms {
          edges {
            node {
              id
              componentProductId
              consumptionTypeId
              allowOverConsumption
              consumptionTypeId
              standardUsage  
            }
          }
        }
        productionSetupOutputSteps{
          edges{
            node{
              productStrategyProcessBom{ componentProductId }
              id
              value
              expectedDuration
              productStrategyProcessStepTypeId
              productionSetupOutputStepStatusId
              fileId
              sequence
              productStrategyProcessBomId
              productStrategyProcessBom{ componentProductId }
              unitId
              min
              max
              target
              code
              color
              description
              url
              startAt
              endAt
            }
          }
        }
      }
    }
  }
}

