  $runTime := $duration - $downTime;
  $scheduleId := $scheduleGroup($workunit.scheduleGroupId).getCurrentSchedules($L.time, $L.time, { "inclusive": false })[0].scheduleId; 

  $plannedProductionTime := $duration - $plannedDowntime;
  $availability := $duration? $runTime / $plannedProductionTime : 1;
  $pref := $runTime > 0 ? ($idealRateSeconds ? $totalProduction / $runTime / $idealRateSeconds : 1 ) : 0 ;
  $quality := $totalProduction = 0 ? 1 : $totalProduced / $totalProduction;

