data.query:
query WorkOrder(
  $where: WorkOrderWhereInput
  $orderBy: [WorkOrderOrderByInput!]
  $first: Int
  $after: String
) {
  workOrder(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        active
        buildToOrder
        buildToStock
        workOrderStatusId
        workOrderStatus {
          id
          system
          usable
          description
          externalId
          name
        }
        workOrderProcesses {
          edges {
            node {
              id
              workOrderProcessDistributions(
                where: {
                  _and: [
                    {
                      distributionStatusId: {
                        _in: ["Planned", "Released", "Scheduled"]
                      }
                    }
                  ]
                }
              ) {
                total
                edges {
                  node {
                    id
                    dispatchSequence
                    distributionStatusId
                    distributionStatus {
                      id
                      system
                      usable
                      description
                      externalId
                      name
                    }
                  }
                }
              }
              inProcessDistributionCount: workOrderProcessDistributions(
                where: {
                  _and: [{ distributionStatusId: { _in: ["In Process"] } }]
                }
              ) {
                total
              }
            }
          }
        }
      }
    }
  }
}

